package com.kidsvideo.app;
import android.content.Context; import android.content.SharedPreferences; import java.time.LocalDate;
public final class TimeLimit { private static final String PREF="watch_time"; private final SharedPreferences p; private final Prefs prefs; private long startedAt=0; public TimeLimit(Context c){p=c.getSharedPreferences(PREF,Context.MODE_PRIVATE);prefs=new Prefs(c);} private String key(){return "seconds_"+LocalDate.now();} public long watchedSecondsToday(){return p.getLong(key(),0L);} public boolean canWatch(){int limit=prefs.dailyLimitMinutes();return limit<=0||watchedSecondsToday()<(long)limit*60L;} public long remainingSeconds(){int limit=prefs.dailyLimitMinutes();if(limit<=0)return Long.MAX_VALUE;return Math.max(0,(long)limit*60L-watchedSecondsToday());} public void start(){if(startedAt==0)startedAt=System.currentTimeMillis();} public void stop(){if(startedAt!=0){long elapsed=Math.max(0,(System.currentTimeMillis()-startedAt)/1000L);p.edit().putLong(key(),watchedSecondsToday()+elapsed).apply();startedAt=0;}} }
